'use strict';
// Inspect and run the actual NSIS-delivered candidate in private folders only.
const fs=require('node:fs'),path=require('node:path'),cp=require('node:child_process');
const {unpack,sha,json,MANIFEST}=require('../build-platform-performance.cjs'),asar=require('@electron/asar');
const ROOT=path.resolve(__dirname,'..'),out=path.join(ROOT,'qa-results/win32-x64'),reportFile=path.join(ROOT,'dist/win32-x64/deliverables/windows-platform-package.json');
const check=(ok,message)=>{if(!ok)throw Error(message);};
async function main(){check(process.platform==='win32'&&process.arch==='x64','Windows x64 required');check(!fs.existsSync(out),'Preserve previous QA');fs.mkdirSync(out,{recursive:true});const report=JSON.parse(fs.readFileSync(reportFile)),installer=path.resolve(ROOT,report.installer.path);check(sha(installer)===report.installer.sha256&&fs.statSync(installer).size===report.installer.bytes,'Candidate installer differs');
  const applications=path.join(out,'Programs'),platform=path.join(applications,'SYNKPlatformPreview');await unpack(installer,platform);const bundles={},checks=[];
  for(const id of ['platform','world','messenger']){const name={platform:'SYNKPlatformPreview',world:'SYNKWorldPreview',messenger:'SYNKMessengerPreview'}[id],directory=path.join(applications,name);if(id!=='platform')await unpack(path.join(platform,'resources/clients',id+'.exe'),directory);const archive=path.join(directory,'resources/app.asar'),executable=path.join(directory,name+'.exe'),metadata=JSON.parse(fs.readFileSync(path.join(directory,'resources/synk-install.json')));check(metadata.clientId===id&&metadata.platform==='win32'&&metadata.arch==='x64','Delivered identity differs '+id);const pin=id==='platform'?{executableSHA256:report.executable.sha256,asarSHA256:report.asar.sha256}:report.children.find(c=>c.id===id).release;check(sha(executable)===pin.executableSHA256&&sha(archive)===pin.asarSHA256,'Delivered executable/ASAR pin differs '+id);bundles[id]={archive,executable,version:metadata.version};checks.push({name:id+' actual NSIS contents verified',ok:true,version:metadata.version});}
  for(const entry of MANIFEST.files){const contents=asar.extractFile(bundles.platform.archive,path.normalize(entry.file));const hash=require('node:crypto').createHash('sha256').update(contents).digest('hex');check(hash===entry.afterSHA256,'Performance code not delivered');}
  const runtime=JSON.parse(asar.extractFile(bundles.platform.archive,'runtime.json'));for(const pin of MANIFEST.windows.additionalLegacyPins)check(runtime.releases.some(item=>JSON.stringify(item)===JSON.stringify(pin)),'Trusted legacy launch pin missing');
  const configFile=path.join(out,'native-config.json');json(configFile,{arch:'x64',applications,bundles});const nativeOut=path.join(out,'platform');const env={...process.env};delete env.ELECTRON_RUN_AS_NODE;delete env.ELECTRON_NO_ASAR;
  const result=cp.spawnSync(process.execPath,[path.join(__dirname,'native-smoke.cjs'),'--config='+configFile,'--out='+nativeOut,'--mode=platform'],{encoding:'utf8',windowsHide:true,env,timeout:190000,maxBuffer:6e6});fs.writeFileSync(path.join(out,'platform-process.log'),(result.stdout||'')+(result.stderr||''));check(result.status===0,'Native Platform QA failed: '+(result.stderr||result.stdout));const native=JSON.parse(fs.readFileSync(path.join(nativeOut,'report.json')));check(native.ok,'Native report failed');
  const final={ok:true,checkedAt:new Date().toISOString(),version:report.version,checks,nativeChecks:native.result.checks,actualInstallerReextracted:true,platformHashVerifierUsed:true,childInstallersUnchanged:true,installerExecuted:false,realProfileTouched:false,realAuthenticationPerformed:false};json(path.join(out,'windows-native-qa.json'),final);console.log(JSON.stringify(final));
}
main().catch(error=>{json(path.join(out,'failure.json'),{ok:false,error:error.stack||error.message});console.error(error.stack||error);process.exitCode=1;});
